mapper.sql:
SELECT pp1.MDATE mdate, pp1.PROFIT_TYPE profitType, futureCash.payDate, futureCash.portfolioId, futureCash.ccy, futureCash.cashType, case when futureCash.cashType = '01' then sum(futureCash.cashAmt) else 0 end assetPeriodInAmt, case when futureCash.cashType = '02' then sum(futureCash.cashAmt) else 0/-1 end assetPeriodOutAmt, case when futureCash.cashType = '03' then sum(futureCash.cashAmt) else 0/-1 end prdEndAmt, case when futureCash.cashType = '04' then sum(futureCash.cashAmt) else 0 end usableAmt from (
union all
union all
) futureCash LEFT JOIN PTL_PORTFOLIO pp1 ON futureCash.portfolioId = pp1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON futureCash.portfolioId = FIN_PRODUCT.FINPROD_MARKET_ID AND FIN_PRODUCT.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F16}) LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
pp1.PROFIT_TYPE = #{profitType}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
AND pp1.PORTFOLIO_ID IN
#{item}
group by pp1.MDATE, pp1.PROFIT_TYPE, futureCash.payDate, futureCash.portfolioId, futureCash.ccy, futureCash.cashType order by futureCash.payDate

SELECT PTL_SEC_POSITION.FINPROD_ID finprodId, FIN_CASH_PLAN.PAY_DATE payDate, PTL_PORTFOLIO.PORTFOLIO_ID portfolioId, FIN_PRODUCT.CCY ccy, '01' cashType, ROUND(PTL_SEC_POSITION.AMOUNT * FIN_CASH_PLAN.CASH_AMT, 2) cashAmt FROM PTL_PORTFOLIO INNER JOIN ( SELECT SUM(AMOUNT) AMOUNT, PORTFOLIO_ID, FINPROD_ID FROM PTL_SEC_POSITION WHERE CDATE = TO_DATE(#{cdate}, 'YYYY-MM-DD') AND HODING_TYPE = #{POSITION_TYPE_03} GROUP BY PORTFOLIO_ID, FINPROD_ID ) PTL_SEC_POSITION ON PTL_SEC_POSITION.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN FIN_CASH_PLAN ON PTL_SEC_POSITION.FINPROD_ID = FIN_CASH_PLAN.FINPROD_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = PTL_SEC_POSITION.FINPROD_ID WHERE PTL_PORTFOLIO.PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01} AND FIN_CASH_PLAN.PAY_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND TO_DATE(#{endDate}, 'YYYY-MM-DD') >= FIN_CASH_PLAN.PAY_DATE AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND FIN_PRODUCT.FINPROD_TYPE2 IN
#{item}
AND ( FIN_PRODUCT.IS_RIGHT = #{YES_OR_NO_N} OR FIN_PRODUCT.IS_RIGHT IS NULL) AND PTL_SEC_POSITION.AMOUNT != 0

SELECT PTL_SEC_POSITION.FINPROD_ID finprodId, FIN_CASH_PLAN.PAY_DATE payDate, PTL_PORTFOLIO.PORTFOLIO_ID portfolioId, FIN_PRODUCT.CCY ccy, '01' cashType, ROUND(PTL_SEC_POSITION.AMOUNT * FIN_CASH_PLAN.CASH_AMT, 2) cashAmt FROM PTL_PORTFOLIO INNER JOIN ( SELECT SUM(AMOUNT) AMOUNT, PORTFOLIO_ID, FINPROD_ID FROM PTL_SEC_POSITION WHERE CDATE = TO_DATE(#{cdate}, 'YYYY-MM-DD') AND HODING_TYPE = #{POSITION_TYPE_03} GROUP BY PORTFOLIO_ID, FINPROD_ID ) PTL_SEC_POSITION ON PTL_SEC_POSITION.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN FIN_CASH_PLAN ON PTL_SEC_POSITION.FINPROD_ID = FIN_CASH_PLAN.FINPROD_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = PTL_SEC_POSITION.FINPROD_ID WHERE PTL_PORTFOLIO.PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01} AND FIN_CASH_PLAN.PAY_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND TO_DATE(#{endDate}, 'YYYY-MM-DD') >= FIN_CASH_PLAN.PAY_DATE AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND FIN_PRODUCT.FINPROD_TYPE2 IN
#{item}
AND FIN_PRODUCT.IS_RIGHT = #{YES_OR_NO_Y} AND PTL_SEC_POSITION.AMOUNT != 0 AND ( ( SELECT MIN(FIN_EXERCISE_PLAN.EXERCISE_DATE) FROM FIN_EXERCISE_PLAN WHERE FIN_EXERCISE_PLAN.EXERCISE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND FIN_EXERCISE_PLAN.EXERCISE_TYPE IN (#{EXEC_MODE_01}, #{EXEC_MODE_02}) AND FIN_PRODUCT.FINPROD_ID = FIN_EXERCISE_PLAN.FINPROD_ID ) IS NULL OR FIN_CASH_PLAN.PAY_DATE < ( SELECT MIN(FIN_EXERCISE_PLAN.EXERCISE_DATE) FROM FIN_EXERCISE_PLAN WHERE FIN_EXERCISE_PLAN.EXERCISE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND FIN_EXERCISE_PLAN.EXERCISE_TYPE IN (#{EXEC_MODE_01}, #{EXEC_MODE_02}) AND FIN_PRODUCT.FINPROD_ID = FIN_EXERCISE_PLAN.FINPROD_ID ) )

SELECT PTL_SEC_POSITION.FINPROD_ID finprodId, fep.ACT_EXERCISE_DATE payDate, PTL_PORTFOLIO.PORTFOLIO_ID portfolioId, FIN_PRODUCT.CCY ccy, '01' cashType, ROUND(PTL_SEC_POSITION.AMOUNT * fep.EXERCISE_PRICE, 2) cashAmt FROM PTL_PORTFOLIO INNER JOIN ( SELECT SUM(AMOUNT) AMOUNT, PORTFOLIO_ID, FINPROD_ID FROM PTL_SEC_POSITION WHERE CDATE = TO_DATE(#{cdate}, 'YYYY-MM-DD') AND HODING_TYPE = #{POSITION_TYPE_03} GROUP BY PORTFOLIO_ID, FINPROD_ID ) PTL_SEC_POSITION ON PTL_SEC_POSITION.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = PTL_SEC_POSITION.FINPROD_ID LEFT JOIN FIN_EXERCISE_PLAN fep ON PTL_SEC_POSITION.FINPROD_ID = fep.FINPROD_ID and fep.EXERCISE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND fep.EXERCISE_TYPE IN (#{EXEC_MODE_01}, #{EXEC_MODE_02}) AND not exists ( SELECT 1 FROM FIN_EXERCISE_PLAN fep2 WHERE fep2.EXERCISE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND fep2.EXERCISE_TYPE IN (#{EXEC_MODE_01}, #{EXEC_MODE_02}) AND fep.FINPROD_ID = fep2.FINPROD_ID and fep.EXERCISE_DATE>fep2.EXERCISE_DATE ) WHERE PTL_PORTFOLIO.PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01} AND fep.EXERCISE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND TO_DATE(#{endDate}, 'YYYY-MM-DD') >= fep.EXERCISE_DATE AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND FIN_PRODUCT.FINPROD_TYPE2 IN
#{item}
AND FIN_PRODUCT.IS_RIGHT = #{YES_OR_NO_Y} AND fep.ACT_EXERCISE_DATE IS NOT NULL AND PTL_SEC_POSITION.AMOUNT != 0

SELECT PTL_PORTFOLIO.PORTFOLIO_ID finprodId, PTL_PORTFOLIO.MDATE payDate, PTL_PORTFOLIO.PORTFOLIO_ID portfolioId, '${CCY_CNY}' ccy, '03' cashType, nvl(BOK_POSITION_PRD.TDY_PRIN_AMT, 0) + nvl(BOK_POSITION_PRD.TDY_UNPAID_INTINCEXP, 0) + ROUND(BOK_POSITION_PRD.TDY_PRIN_AMT * nvl(FIN_CASH_CALC_RULE.YIELD, 0) * (PTL_PORTFOLIO.MDATE - TO_DATE('${cdate}', 'YYYY-MM-DD')) / (case when FIN_CASH_CALC_RULE.BASIS = '${BASIS_A_360}' then 360 else 365 end), 2) cashAmt FROM PTL_PORTFOLIO INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_MARKET_ID = PTL_PORTFOLIO.PORTFOLIO_ID AND FIN_PRODUCT.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F16}) INNER JOIN BOK_POSITION_PRD ON BOK_POSITION_PRD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND BOK_POSITION_PRD.BRANCH = 0 AND BOK_POSITION_PRD.CDATE = TO_DATE(#{cdate}, 'YYYY-MM-DD') - 1 LEFT JOIN FIN_CASH_INFO ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND FIN_CASH_INFO.CASH_TYPE_2 = #{CASH_TYPE_2_C02} LEFT JOIN FIN_CASH_CALC_RULE ON FIN_CASH_INFO.CASH_ID = FIN_CASH_CALC_RULE.CASH_ID AND TO_DATE(#{endDate}, 'YYYY-MM-DD') >= FIN_CASH_CALC_RULE.EFF_DATE AND NOT EXISTS (SELECT 1 FROM FIN_CASH_CALC_RULE fccrTemp WHERE fccrTemp.CASH_ID = FIN_CASH_CALC_RULE.CASH_ID AND TO_DATE(#{endDate}, 'YYYY-MM-DD') >= fccrTemp.EFF_DATE AND fccrTemp.EFF_DATE > FIN_CASH_CALC_RULE.EFF_DATE ) WHERE PTL_PORTFOLIO.PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01} AND PTL_PORTFOLIO.PROFIT_TYPE = #{PROFIT_TYPE_02}
AND FIN_PRODUCT.FINPROD_TYPE2 IN
#{item}
AND TO_DATE(#{endDate}, 'YYYY-MM-DD') >= PTL_PORTFOLIO.MDATE AND PTL_PORTFOLIO.MDATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
